const myTag = node.data?.tag || "default";

// --- Détermination du Type via les Handles ---
// Si j'ai un point d'entrée (L), je suis une Source (je reçois le flux et je le téléporte)
// Si j'ai un point de sortie (R), je suis une Target (je commence un flux)
const hasInput = node.handles.L?.point?.length > 0;
const hasOutput = node.handles.R?.point?.length > 0;

// Logique de sécurité : si mal configuré (aucun handle ou les deux), on passe
if (!hasInput && !hasOutput) return data;

log(`Portal Node Tag: "${myTag}" (Mode: ${hasInput ? 'Sender' : 'Receiver'})`);

// --- Mode Receiver (Target) ---
// Si je suis une Target, je ne fais rien de spécial ici.
// Mon exécution est déclenchée par "nextFromNode" qui cible mes edges sortants directement.
// Si le flux arrive ici par erreur, on renvoie juste la data.
if (hasOutput) {
  console.log("aaaa");
    return data;
}

// --- Mode Sender (Source) ---
// Si je suis une Source, je cherche le portal correspondant
if (hasInput) {
    let targetNode = null;

    // On parcourt tous les nodes pour trouver le jumeau
    for (const [id, candidate] of nodeMap) {
        // On cherche un autre portal (même type de node), différent de moi
        if (candidate.type === node.type && candidate._key !== node._key) {
            const candidateTag = candidate.data?.tag || "default";

            // On vérifie si ce candidat est un Récepteur (il doit avoir un handle R)
            const candidateHasOutput = candidate.handles.R?.point?.length > 0;
            // Match trouvé : même tag et c'est un récepteur
            if (candidateHasOutput && candidateTag === myTag) {
                targetNode = candidate;
                break; 
            }
        }
    }

    if (targetNode) {
        // On récupère le point de sortie du récepteur
        const targetPointId = targetNode.handles.R?.point?.[0]?.id;

        if (targetPointId) {
            log(`Teleporting to portal "${targetNode.data?.label || targetNode.id}"`);
            // On téléporte l'exécution
            return await nextFromNode(targetNode._key, targetPointId, data);
        } else {
            log(`Error: Target portal found but has no output point.`);
        }
    } else {
        log(`Warning: No matching target portal found for tag "${myTag}"`);
    }
}

return data;

