const modalId = `portal-modal`;
const storageKey = `portalModal_${nodeId}`;

if (!globalStorage[storageKey]) {
    // --- Layout ---
    const container = document.createElement("div");
    container.style.cssText = `
        display: flex; flex-direction: column; gap: 24px; padding: 24px;
        background: var(--nodius-background-paper); height: 100%;
        color: var(--nodius-text-primary);
    `;

    // --- Title ---
    const title = document.createElement("h3");
    title.textContent = "Portal Configuration";
    title.style.margin = "0 0 16px 0";
    container.appendChild(title);

    // --- Tag Input ---
    const tagGroup = document.createElement("div");
    const tagLabel = document.createElement("label");
    tagLabel.textContent = "Link Name (Tag)";
    tagLabel.style.cssText = "display: block; margin-bottom: 8px; font-weight: 500;";

    const tagInput = document.createElement("input");
    tagInput.type = "text";
    tagInput.placeholder = "e.g., process-payment";
    tagInput.style.cssText = `
        width: 100%; padding: 10px; border-radius: 6px;
        background: var(--nodius-background-default);
        border: 1px solid var(--nodius-primary-dark);
        color: var(--nodius-text-primary);
    `;
    tagGroup.appendChild(tagLabel);
    tagGroup.appendChild(tagInput);
    container.appendChild(tagGroup);

    // --- Type Selection (Radio Cards) ---
    const typeLabel = document.createElement("label");
    typeLabel.textContent = "Portal Type";
    typeLabel.style.cssText = "display: block; margin-bottom: 8px; font-weight: 500;";
    container.appendChild(typeLabel);

    const typeContainer = document.createElement("div");
    typeContainer.style.cssText = "display: flex; gap: 16px;";

    // Helper for cards
    const createCard = (value, label, iconSvg, desc) => {
        const card = document.createElement("div");
        card.dataset.value = value;
        card.style.cssText = `
            flex: 1; padding: 16px; border-radius: 8px; cursor: pointer;
            border: 2px solid transparent; background: var(--nodius-background-default);
            transition: all 0.2s; display: flex; flex-direction: column; align-items: center; gap: 8px; text-align: center;
        `;
        card.innerHTML = `
            <div style="color: var(--nodius-primary-main);">${iconSvg}</div>
            <div style="font-weight: 600;">${label}</div>
            <div style="font-size: 12px; opacity: 0.7;">${desc}</div>
        `;
        return card;
    };

    const sourceCard = createCard(
        "source", 
        "Sender (Input)", 
        `<svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M2 12h17"/><path d="m15 8 4 4-4 4"/><path d="M21 12v.01"/></svg>`,
        "Receives flow and teleports it elsewhere."
    );

    const targetCard = createCard(
        "target", 
        "Receiver (Output)", 
        `<svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12H5"/><path d="m9 16-4-4 4-4"/><path d="M3 12v.01"/></svg>`,
        "Starts a new flow execution from here."
    );

    typeContainer.appendChild(sourceCard);
    typeContainer.appendChild(targetCard);
    container.appendChild(typeContainer);

    // --- Helper to update Handle Structure ---
    // C'est la partie critique : on modifie la structure du node (L/R) selon le choix
    const updateHandles = async (type) => {
        const node = getNode(nodeId);
        let hasChanged = false;

        if (type === "source") {
            // Source: Needs 1 Incoming (L), 0 Outgoing (R)
            if (!node.handles.L?.point?.length) {
                 node.handles.L = { position: "left", point: [{ 
                     id: generateUniqueHandlePointId(nodeId), 
                     type: "in", accept: "any", display: "" 
                 }] };
                 hasChanged = true;
            }
            if (node.handles.R?.point?.length > 0) {
                node.handles.R = { position: "right", point: [] };
                hasChanged = true;
            }
        } else {
            // Target: Needs 0 Incoming (L), 1 Outgoing (R)
            if (node.handles.L?.point?.length > 0) {
                node.handles.L = { position: "left", point: [] };
                hasChanged = true;
            }
            if (!node.handles.R?.point?.length) {
                node.handles.R = { position: "right", point: [{ 
                    id: generateUniqueHandlePointId(nodeId), 
                    type: "out", accept: "any", display: "" 
                }] };
                hasChanged = true;
            }
        }

        if (hasChanged) {
            await updateNode(node);
        }
    };

    // --- Event Listeners ---
    const cards = [sourceCard, targetCard];

    const selectType = async (selectedType) => {
        cards.forEach(c => {
            if (c.dataset.value === selectedType) {
                c.style.borderColor = "var(--nodius-primary-main)";
                c.style.background = "rgba(25, 118, 210, 0.1)";
            } else {
                c.style.borderColor = "transparent";
                c.style.background = "var(--nodius-background-default)";
            }
        });

        const node = getNode(nodeId);
        // Sauvegarde dans node.data
        if (!node.data) node.data = {};
        if (node.data.portalType !== selectedType) {
            node.data.portalType = selectedType;
            await updateHandles(selectedType);
            await updateNode(node);
        }
    };

    cards.forEach(card => {
        card.addEventListener("click", () => selectType(card.dataset.value));
    });

    tagInput.addEventListener("blur", async () => {
        const node = getNode(nodeId);
        if (!node.data) node.data = {};
        node.data.tag = tagInput.value;
        // On met à jour le label du node pour voir le tag directement sur le graph
        node.data.label = `Portal: ${tagInput.value}`;
        await updateNode(node);
    });

    globalStorage[storageKey] = {
        container,
        tagInput,
        selectType,
        updateHandles
    };
}

const state = globalStorage[storageKey];

