const myTag = node.data?.tag || "default";
const myType = node.data?.portalType || "source"; // "source" or "target"

log(`Portal Node (${myType}) - Tag: "${myTag}"`);

// Si c'est un récepteur, il sert juste de point de départ, 
// donc s'il est exécuté directement, il passe juste la main.
if (myType === 'target') {
    return data;
}

// Si c'est un émetteur (source), on cherche le récepteur correspondant
if (myType === 'source') {
    let targetNode = null;

    // On itère sur la map des nodes disponible dans l'environnement
    // Note: nodeMap est une Map<string, Node>
    for (const [id, candidate] of nodeMap) {
        // On cherche un autre portal, qui n'est pas moi-même
        if (candidate.type === node.type && candidate.id !== node.id) {
            const candidateTag = candidate.data?.tag || "default";
            const candidateType = candidate.data?.portalType || "source";

            // Il faut que ce soit un récepteur avec le même tag
            if (candidateType === 'target' && candidateTag === myTag) {
                targetNode = candidate;
                break; 
            }
        }
    }

    if (targetNode) {
        // On récupère le point de sortie du récepteur (Handle R)
        const targetPointId = targetNode.handles.R?.point?.[0]?.id;

        if (targetPointId) {
            log(`Teleporting to portal "${targetNode.data?.label || targetNode.id}"`);
            // C'est ici que la magie opère : on déclenche la suite depuis l'autre node
            // On attend la fin de l'exécution de la branche distante
            return await nextFromNode(targetNode.id, targetPointId, data);
        } else {
            log(`Error: Target portal found but has no output point.`);
        }
    } else {
        log(`Warning: No matching target portal found for tag "${myTag}"`);
    }
}

return data;

