                border: none; border-radius: 6px; cursor: pointer; width: 28px; height: 28px;
                display: flex; align-items: center; justify-content: center;
            `;

            deleteBtn.addEventListener("click", async (e) => {
                e.stopPropagation();
                const currentNode = getNode(nodeId);
                const currentPoints = currentNode.handles.R?.point || [];
                if (currentPoints.length <= 1) return; // Prevent deleting last output

                const idx = parseInt(row.dataset.index);
                currentPoints.splice(idx, 1);

                if (state.selectedRowIndex === idx) state.selectedRowIndex = null;
                else if (state.selectedRowIndex > idx) state.selectedRowIndex--;

                await updateNode(currentNode);
                state.refresh();
            });

            actionsCell.appendChild(deleteBtn);
            row.appendChild(actionsCell);

            // Row Interaction
            row.style.transition = "background 0.2s";
            row.style.cursor = "pointer";
            row.addEventListener("click", () => {
                state.selectedRowIndex = parseInt(row.dataset.index);
                state.refresh();
            });

        } // End creating new row

        // Update Content
        row.dataset.index = index.toString();

        // Highlight logic
        const isSelected = state.selectedRowIndex === index;
        row.style.background = isSelected ? "var(--nodius-grey-300)" : (index % 2 === 0 ? "var(--nodius-background-paper)" : "var(--nodius-background-default)");

        row.children[0].textContent = (index + 1).toString(); // Order
        row.children[1].querySelector("input").value = point.display || "";

        return row;
    };
}

// --- Refresh Logic ---
if (!state.refresh) {
    state.refresh = () => {
        const node = getNode(nodeId);
        // Assure R handle exists
        if (!node.handles.R) node.handles.R = { position: "separate", point: [] };
        const points = node.handles.R.point;

        const currentRows = Array.from(state.tbody.children);

        points.forEach((point, index) => {
            let row = currentRows[index];
            row = state.createOrUpdateRow(node, row, point, index);
            if (!state.tbody.contains(row)) state.tbody.appendChild(row);
        });

        // Remove excess rows
        while (state.tbody.children.length > points.length) {
            state.tbody.removeChild(state.tbody.lastChild);
        }

        // Handle delete button state (disable if only 1 item)
        state.tbody.querySelectorAll('td button').forEach(btn => {
            if (points.length <= 1) {
                btn.style.opacity = "0.3"; btn.style.cursor = "not-allowed";
            } else {
                btn.style.opacity = "1"; btn.style.cursor = "pointer";
            }
        });

        state.updateActionButtons();
    };
}

// --- Action Buttons (Right Panel) ---
if (!state.updateActionButtons) {
    state.updateActionButtons = () => {
        state.actionsContainer.innerHTML = "";

        const createBtn = (icon, title, colorVar, onClick, isDisabled) => {
            const btn = document.createElement("button");
            btn.innerHTML = icon;
            btn.title = title;
            btn.style.cssText = `
                padding: 4px; background: var(--${colorVar}-main); color: var(--${colorVar}-contrastText);
                border: none; border-radius: 6px; cursor: pointer; width: 28px; height: 28px;
                display: flex; align-items: center; justify-content: center; transition: all 0.2s;
            `;
            if (isDisabled) {
                btn.style.opacity = "0.3"; btn.style.cursor = "not-allowed";
            } else {
                btn.addEventListener("click", onClick);
                btn.addEventListener("mouseenter", () => btn.style.transform = "scale(1.05)");
                btn.addEventListener("mouseleave", () => btn.style.transform = "scale(1)");
            }
            return btn;
        };

        const node = getNode(nodeId);
        const points = node.handles.R?.point || [];
        const sel = state.selectedRowIndex;

        // Move Up
        const upIcon = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 12 7-7 7 7"/><path d="M12 19V5"/></svg>`;
        state.actionsContainer.appendChild(createBtn(upIcon, "Move Up", "nodius-info", async () => {
            const temp = points[sel]; points[sel] = points[sel - 1]; points[sel - 1] = temp;
            state.selectedRowIndex = sel - 1;
            await updateNode(node); state.refresh();
        }, sel === null || sel <= 0));

        // Move Down
        const downIcon = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14"/><path d="m19 12-7 7-7-7"/></svg>`;
        state.actionsContainer.appendChild(createBtn(downIcon, "Move Down", "nodius-info", async () => {
            const temp = points[sel]; points[sel] = points[sel + 1]; points[sel + 1] = temp;
            state.selectedRowIndex = sel + 1;
            await updateNode(node); state.refresh();
        }, sel === null || sel >= points.length - 1));

        // Separator
        const sep = document.createElement("div");
        sep.style.cssText = "height: 1px; width: 80%; background: rgba(255,255,255,0.1); margin: 8px 0;";
        state.actionsContainer.appendChild(sep);

        // Add Button
        const addIcon = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14"/><path d="M12 5v14"/></svg>`;
        state.actionsContainer.appendChild(createBtn(addIcon, "Add Output", "nodius-success", async () => {
            const newNode = getNode(nodeId);
            if (!newNode.handles.R) newNode.handles.R = { position: "separate", point: [] };

            const newPoint = {
                id: generateUniqueHandlePointId(nodeId),
                type: "out",
                accept: "any",
                display: `Output ${newNode.handles.R.point.length + 1}`
            };
            newNode.handles.R.point.push(newPoint);
            await updateNode(newNode);
            state.selectedRowIndex = newNode.handles.R.point.length - 1;
            state.refresh();
        }, false));
    };
}

// Initial Load
state.refresh();

if (!modalManager.isOpen(modalId)) {
    modalManager.open({
        id: modalId,
        nodeId: nodeId,
        title: `Multiplexer Configuration`,
        content: state.modalContainer,
        width: "600px",
        height: "500px",
        closeIfExists: false
    });
}

node.process:
// Récupération de la donnée entrante
const data = incoming ? incoming.data : undefined;
log(`Multiplexer processing sequence with data: ${JSON.stringify(data)}`);

const points = node.handles.R?.point || [];
let allResults = [];

// Exécution SÉQUENTIELLE
// On boucle sur chaque point de sortie configuré
for (const [index, point] of points.entries()) {
    log(`[Sequence ${index + 1}/${points.length}] Triggering output: ${point.display} (${point.id})`);

    try {
        // Le "await" ici est crucial : il attend que TOUTE la branche connectée 
        // à ce point soit terminée avant de passer à l'itération suivante.
        const branchResult = await next(point.id, data);

        // On collecte les résultats si nécessaire (optionnel, dépend de ton usage)
        if (branchResult) {
            allResults.push({ output: point.display, result: branchResult });
        }
    } catch (e) {
        log(`Error executing sequence for output ${point.display}: ${e.message}`);
        // On continue quand même vers le prochain output ? 
        // Si tu veux arrêter en cas d'erreur, ajoute un "break" ou "throw e" ici.
    }
}

log(`Multiplexer sequence completed.`);

// Si c'est un node d'entrée (pas d'incoming), on stocke le résultat
if (!incoming) {
    global.result = data;
}

// Le multiplexer renvoie généralement la donnée passante originale
// pour permettre le chaining si besoin, ou le résultat agrégé.
return data;

